public class Device {
 public string ConfigDescription {get;set;} public List<ConfigAttachment> Attachments {get;set;}
 public List<NetworkConnection> Connections {get;set;} public List<string> SourceRecords {get;set;}
 public string IconData {get;set;}
 public Dictionary<string,string> Details {get;set;}
 public string Id {get;set;} public string Name {get;set;} public string Address {get;set;} public string Url {get;set;} public string Group {get;set;}
 public Device() { Details=new Dictionary<string,string>(); Id=Guid.NewGuid().ToString(); Name=""; Address=""; Url=""; Group="General"; }
}
public class NetworkConnection {
 public AccessOptions Access {get;set;}
 public string Id {get;set;} public string Kind {get;set;} public string Name {get;set;} public string Connectivity {get;set;} public string Address {get;set;} public string Url {get;set;} public Dictionary<string,string> Details {get;set;}
 public NetworkConnection(){Id=Guid.NewGuid().ToString();Kind="Other";Name="Other";Connectivity="";Address="";Url="";Details=new Dictionary<string,string>();}
}
public static class DeviceConnections {
 static readonly string[] Fields={"Connectivity","MAC","IP range","Item","Network reference","Local dashboard URL","Original dashboard link","Source","Import review"};
 public static string Get(Dictionary<string,string> values,string key){string v;return values.TryGetValue(key,out v)?v:"";}
 public static void Normalize(Device d){
  if(d.Details==null)d.Details=new Dictionary<string,string>();if(d.SourceRecords==null)d.SourceRecords=new List<string>();
  if(d.Connections==null){string connectivity=Get(d.Details,"Connectivity");string kind=connectivity.IndexOf("wifi",StringComparison.OrdinalIgnoreCase)>=0?"Wi-Fi":(connectivity.IndexOf("cable",StringComparison.OrdinalIgnoreCase)>=0||connectivity.IndexOf("baset",StringComparison.OrdinalIgnoreCase)>=0?"Cable":"Other");var c=new NetworkConnection{Kind=kind,Name=kind,Connectivity=connectivity,Address=d.Address??"",Url=d.Url??""};
   foreach(var pair in d.Details.ToArray())if(Fields.Contains(pair.Key)||pair.Key.StartsWith("Recorded ")){if(pair.Key!="Connectivity")c.Details[pair.Key]=pair.Value;d.Details.Remove(pair.Key);}d.Connections=new List<NetworkConnection>{c};
  }
  if(d.Connections.Count>32)throw new Exception("A device can have up to 32 connections.");
  var ids=new HashSet<string>();foreach(var c in d.Connections){if(c==null)throw new Exception("Invalid connection.");if(c.Details==null)c.Details=new Dictionary<string,string>();if(String.IsNullOrEmpty(c.Id)||!ids.Add(c.Id)){c.Id=Guid.NewGuid().ToString();ids.Add(c.Id);}c.Name=(c.Name??"").Trim();if(c.Name.Length==0)c.Name=c.Kind??"Other";if(c.Name.Length>100)throw new Exception("Connection name is too long.");if(c.Kind!="Cable"&&c.Kind!="Wi-Fi"&&c.Kind!="Other")throw new Exception("Choose Cable, Wi-Fi or Other for the connection.");c.Connectivity=c.Connectivity??"";c.Address=(c.Address??"").Trim();c.Url=(c.Url??"").Trim();Config.ValidateEndpoint(c.Address,c.Url);}
  d.Address=d.Connections.Count>0?d.Connections[0].Address:"";d.Url=d.Connections.Count>0?d.Connections[0].Url:"";
 }
 public static Device Clone(Device d){return Config.Decode(Config.Encode(new List<Device>{d}))[0];}
 public static Device Combine(Device primary,Device secondary){
  if(primary.Id==secondary.Id)throw new Exception("Choose two different records.");var a=Clone(primary);var b=Clone(secondary);
  a.SourceRecords.Add(Config.Encode(new List<Device>{primary}));a.SourceRecords.Add(Config.Encode(new List<Device>{secondary}));
  foreach(var c in b.Connections){if(a.Connections.Any(x=>x.Id==c.Id))c.Id=Guid.NewGuid().ToString();a.Connections.Add(c);}
  foreach(var pair in b.Details)if(!a.Details.ContainsKey(pair.Key)||String.IsNullOrWhiteSpace(a.Details[pair.Key]))a.Details[pair.Key]=pair.Value;
  if(String.IsNullOrEmpty(a.IconData))a.IconData=b.IconData;Config.Validate(a);return a;
 }
 public static string DescribeSource(string json){var d=Config.Decode(json)[0];var lines=new List<string>{"Device: "+d.Name,"Category: "+d.Group,"Record ID: "+d.Id};lines.AddRange(d.Details.Select(p=>p.Key+": "+p.Value));foreach(var c in d.Connections){lines.Add("");lines.Add("Connection: "+c.Name+" ("+c.Kind+")");lines.Add("Address: "+c.Address);lines.Add("Dashboard URL: "+c.Url);lines.Add("Connectivity: "+c.Connectivity);lines.AddRange(c.Details.Select(p=>p.Key+": "+p.Value));}return String.Join("\r\n",lines);}
 public static string Summary(Device d){return String.Join("; ",d.Connections.Select(c=>c.Name+": "+(c.Address.Length>0?c.Address:"not recorded")));}
 public static string Search(Device d){return String.Join(" ",d.Connections.Select(c=>c.Name+" "+c.Connectivity+" "+c.Address+" "+c.Url+" "+String.Join(" ",c.Details.Values)));}
}

public static class DeviceImages {
 public static Image Read(string data){if(String.IsNullOrEmpty(data))return null;try{using(var stream=new MemoryStream(Convert.FromBase64String(data)))using(var original=Image.FromStream(stream)){var copy=new Bitmap(original.Width,original.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(copy)){g.CompositingMode=System.Drawing.Drawing2D.CompositingMode.SourceCopy;g.DrawImageUnscaled(original,0,0);}return copy;}}catch{return null;}}
 public static string Import(string path){using(var original=Image.FromFile(path))using(var thumbnail=new Bitmap(96,96,System.Drawing.Imaging.PixelFormat.Format32bppArgb)){
  using(var g=Graphics.FromImage(thumbnail)){g.Clear(Color.Transparent);g.CompositingMode=System.Drawing.Drawing2D.CompositingMode.SourceCopy;g.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;float scale=Math.Min(96f/original.Width,96f/original.Height);float w=original.Width*scale,h=original.Height*scale;g.DrawImage(original,(96-w)/2,(96-h)/2,w,h);}
  using(var stream=new MemoryStream()){thumbnail.Save(stream,System.Drawing.Imaging.ImageFormat.Png);return Convert.ToBase64String(stream.ToArray());}
 }}
}
public static class Config {
 public static readonly string Folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"HomelabDashboard");
 public static readonly string LegacyPath=Path.Combine(Folder,"devices.json");
 public static readonly string OlderPath=Path.Combine(Folder,"devices-v3.json");
 public static readonly string PreviousPath=Path.Combine(Folder,"devices-v4.json");
 public static readonly string PathName=Path.Combine(Folder,"devices-v5.json");
 public static string Encode(List<Device> list) {return new JavaScriptSerializer{MaxJsonLength=134217728}.Serialize(list);}
 public static List<Device> Decode(string json) {
  var list=new JavaScriptSerializer{MaxJsonLength=134217728}.Deserialize<List<Device>>(json);
  if(list==null || list.Count>500) throw new Exception("Configuration must contain an array of up to 500 devices.");
  var ids=new HashSet<string>();
  foreach(var d in list) { if(d==null) throw new Exception("Invalid device."); Validate(d); if(String.IsNullOrEmpty(d.Id)||!ids.Add(d.Id)) {d.Id=Guid.NewGuid().ToString();ids.Add(d.Id);} }
  return list;
 }
 public static void Validate(Device d) {
  if(d.Details==null)d.Details=new Dictionary<string,string>();
  d.Name=(d.Name??"").Trim(); d.Address=(d.Address??"").Trim();d.Url=(d.Url??"").Trim();d.Group=(d.Group??"").Trim();
  if(d.Name.Length==0 || d.Name.Length>100) throw new Exception("Enter a device name (up to 100 characters).");
  if(d.Attachments==null)d.Attachments=new List<ConfigAttachment>();long bytes=0;var attachmentIds=new HashSet<string>();foreach(var a in d.Attachments){if(a==null||String.IsNullOrWhiteSpace(a.Name))throw new Exception("Invalid attachment.");if(String.IsNullOrEmpty(a.Id)||!attachmentIds.Add(a.Id))throw new Exception("Invalid attachment identifier.");var length=Convert.FromBase64String(a.Data??"").Length;if(length>1048576)throw new Exception("Each attached file must be at most 1 MB.");bytes+=length;}if(bytes>8388608)throw new Exception("Attachments for one device must total 8 MB or less.");
  DeviceConnections.Normalize(d);
  d.Details.Remove("Original name");foreach(var c in d.Connections){c.Access=c.Access??AccessOptions.Defaults();c.Access.Validate();}
  if(d.Group.Length==0)d.Group="General";
  if(d.Group.Length>60)throw new Exception("Group must be 60 characters or fewer.");
 }
 public static void ValidateEndpoint(string address,string url){
  IPAddress ip;
  if(address.Length>0 && (!(IPAddress.TryParse(address,out ip)||(Uri.CheckHostName(address)==UriHostNameType.Dns && System.Text.RegularExpressions.Regex.IsMatch(address,@"^[A-Za-z0-9][A-Za-z0-9._-]*$"))) || address.Any(c=>Char.IsWhiteSpace(c)||c=='/'||c=='\\'||c=='"'))) throw new Exception("Address must be a hostname or IP address, without a port or URL prefix.");
  Uri uri;
  if(url.Length>0 && (!Uri.TryCreate(url,UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https") || !String.IsNullOrEmpty(uri.UserInfo))) throw new Exception("Dashboard URL must use http:// or https:// and contain no credentials.");
 }
 public static void Save(List<Device> list) {
  SaveTo(list,PathName);
 }
 public static void SaveTo(List<Device> list,string target) {
  Directory.CreateDirectory(Path.GetDirectoryName(target)); var temp=target+".tmp";File.WriteAllText(temp,Encode(list));
  if(File.Exists(target))File.Replace(temp,target,target+".bak");else File.Move(temp,target);
 }
}
