 public static int CompareAddresses(string left,string right){
  left=(left??"").Trim();right=(right??"").Trim();IPAddress a,b;
  bool aIp=IPAddress.TryParse(left,out a),bIp=IPAddress.TryParse(right,out b);
  // Ascending: IPv4, IPv6, hostnames, then missing addresses.
  int aKind=aIp?(a.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork?0:1):(left.Length>0?2:3);
  int bKind=bIp?(b.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork?0:1):(right.Length>0?2:3);
  if(aKind!=bKind)return aKind.CompareTo(bKind);
  if(aIp&&bIp){var aa=a.GetAddressBytes();var bb=b.GetAddressBytes();for(int i=0;i<aa.Length;i++){int order=aa[i].CompareTo(bb[i]);if(order!=0)return order;}return 0;}
  return StringComparer.OrdinalIgnoreCase.Compare(left,right);
 }
 void SetZoom(int value){value=Math.Max(layoutMode?20:60,Math.Min(layoutMode?200:150,value));if(value==zoom)return;zoom=value;zoomLabel.Text=zoom+"%";if(layoutMode&&topology!=null)topology.Canvas.SetZoom(zoom);else Render();}
 public bool PreFilterMessage(ref Message m){
  if(m.Msg!=0x020A || (m.WParam.ToInt64() & 8)==0 || !Enabled)return false;
  var target=Control.FromHandle(m.HWnd);if(target==null || target.FindForm()!=this)return false;
  wheelDelta+=(short)((m.WParam.ToInt64()>>16)&0xffff);
  int steps=wheelDelta/120;wheelDelta%=120;if(steps!=0)SetZoom(zoom+steps*10);return true;
 }
