  list.RowTemplate.Height=Math.Max(21,(int)(40*zoom/100f));list.ColumnHeadersHeight=Math.Max(24,(int)(36*zoom/100f));
  int[] widths={44,180,120,125,105,185,175};
  for(int i=0;i<list.Columns.Count;i++){list.Columns[i].MinimumWidth=Math.Max(35,(int)(widths[i]*zoom/100f));list.Columns[i].FillWeight=widths[i];}
  foreach(var d in filtered){string location,status;d.Details.TryGetValue("Location",out location);statuses.TryGetValue(d.Id,out status);int index=list.Rows.Add(DeviceImages.Read(d.IconData),d.Name,d.Group,Ui.Detail(d,"Device type"),location??"",ShortAddress(d),StatusText(d));var row=list.Rows[index];row.Tag=d;row.Cells[5].ToolTipText=DeviceConnections.Summary(d);row.Cells[6].ToolTipText=statusDetails.ContainsKey(d.Id)?statusDetails[d.Id]:StatusText(d);row.Cells[1].ToolTipText=d.Name+(d.Details.ContainsKey("Import review")?" — Review needed":"");if(d.Id==selected)list.CurrentCell=row.Cells[1];}
  if(sortedColumn!=null)list.Sort(sortedColumn,sortDirection);
  if(first>=0&&list.Rows.Count>0)list.FirstDisplayedScrollingRowIndex=Math.Min(first,list.Rows.Count-1);if(oldFont!=null)oldFont.Dispose();
 }
 void AttachActions(Control control,Device device){control.MouseDown+=(sender,e)=>SelectDevice(device);control.DoubleClick+=(sender,e)=>ViewDevice(device);control.MouseUp+=(sender,e)=>{if(e.Button==MouseButtons.Right)ShowActions(device);};foreach(Control child in control.Controls)AttachActions(child,device);}
 ContextMenuStrip CreateActions(Device d){if(actionMenu==null)actionMenu=new ContextMenuStrip{ShowImageMargin=false};var menu=actionMenu;while(menu.Items.Count>0){var old=menu.Items[0];menu.Items.RemoveAt(0);old.Dispose();}
  var headingFont=new Font(menu.Font,FontStyle.Bold);var heading=new ToolStripMenuItem(d.Name){Font=headingFont};heading.Disposed+=(s,e)=>headingFont.Dispose();menu.Items.Add(heading);menu.Items.Add(new ToolStripSeparator());
  menu.Items.Add("Connection Status",null,(s,e)=>MessageBox.Show(this,statusDetails.ContainsKey(d.Id)?statusDetails[d.Id]:"Not checked. Use Check Status in the main menu to check this device's connections.","Connection Status — "+d.Name));menu.Items.Add(new ToolStripSeparator());
  AddConnectionAction(menu,"Open Dashboard",d,c=>c.Url.Length>0,c=>Launch(c.Url));
  AddConnectionAction(menu,"SSH",d,c=>Links.Available(c,"SSH"),c=>Links.Ssh(c));AddConnectionAction(menu,"RDP",d,c=>Links.Available(c,"RDP"),c=>Links.Rdp(c));AddConnectionAction(menu,"Shared Folders",d,c=>Links.Available(c,"Shared"),c=>Links.Files(c));
  menu.Items.Add(new ToolStripSeparator());menu.Items.Add("Edit Details",null,(s,e)=>Edit(d));menu.Items.Add("Delete Device",null,(s,e)=>Delete(d));return menu;
 }
 void AddConnectionAction(ContextMenuStrip menu,string label,Device d,Func<NetworkConnection,bool> available,Action<NetworkConnection> action){var item=new ToolStripMenuItem(label);menu.Items.Add(item);if(d.Connections.Count==1){var c=d.Connections[0];item.Enabled=available(c);item.Click+=(s,e)=>action(c);}else{item.Enabled=d.Connections.Any(available);foreach(var c in d.Connections){var connection=c;var child=new ToolStripMenuItem(c.Name+" — "+(c.Address.Length>0?c.Address:"no address")){Enabled=available(c)};child.Click+=(s,e)=>action(connection);item.DropDownItems.Add(child);}}}
 void ShowActions(Device d){SelectDevice(d);CreateActions(d).Show(Cursor.Position);}
 protected override void Dispose(bool disposing){if(disposing){if(actionMenu!=null)actionMenu.Dispose();if(mainMenu!=null)mainMenu.Dispose();help.Dispose();refresh.Dispose();}base.Dispose(disposing);}
 protected override void OnFormClosed(FormClosedEventArgs e){Application.RemoveMessageFilter(this);base.OnFormClosed(e);if(viewFont!=null)viewFont.Dispose();}
 void SelectDevice(Device d){selectedDeviceId=d.Id;foreach(Control tile in cards.Controls)tile.Invalidate();}
 Device SelectedDevice(){string id=layoutMode?(topology==null?null:topology.Canvas.SelectedDeviceId):(listMode?(list.CurrentRow==null||list.CurrentRow.Tag==null?null:((Device)list.CurrentRow.Tag).Id):selectedDeviceId);return devices.FirstOrDefault(d=>d.Id==id);}
 void CopySelected(){var source=SelectedDevice();if(source==null)return;try{var copy=DuplicateDevice(source,devices);var next=new List<Device>(devices);next.Add(copy);selectedDeviceId=copy.Id;if(Commit(next))CheckProgress("Copied "+source.Name+" as "+copy.Name+". Save the network to keep this copy.");}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not copy device");}}
 public static Device DuplicateDevice(Device source,List<Device> existing){
  if(existing.Count>=500)throw new Exception("This network already contains the maximum of 500 devices.");
  var copy=DeviceConnections.Clone(source);copy.Id=Guid.NewGuid().ToString();
  foreach(var connection in copy.Connections)connection.Id=Guid.NewGuid().ToString();
  foreach(var attachment in copy.Attachments)attachment.Id=Guid.NewGuid().ToString();
  copy.Details.Remove("Device reference");copy.Details.Remove("Previous device references");
  string name=System.Text.RegularExpressions.Regex.Replace(source.Name,@" - Copy [0-9]+$", "",System.Text.RegularExpressions.RegexOptions.IgnoreCase);int number=0;
  foreach(var d in existing){var match=System.Text.RegularExpressions.Regex.Match(d.Name,@"^(.*) - Copy ([0-9]+)$",System.Text.RegularExpressions.RegexOptions.IgnoreCase);int value;if(match.Success&&String.Equals(match.Groups[1].Value,name.Substring(0,Math.Min(name.Length,100-(" - Copy "+match.Groups[2].Value).Length)),StringComparison.OrdinalIgnoreCase)&&Int32.TryParse(match.Groups[2].Value,out value))number=Math.Max(number,value);}
  do{number=checked(number+1);string suffix=" - Copy "+number;copy.Name=name.Substring(0,Math.Min(name.Length,100-suffix.Length))+suffix;}while(existing.Any(d=>String.Equals(d.Name,copy.Name,StringComparison.OrdinalIgnoreCase)));
  Config.Validate(copy);return copy;
 }
 bool Commit(List<Device> next){try{if(!loaded)throw new Exception("Import a valid configuration before editing. Your unreadable configuration has been preserved.");foreach(var d in next)Config.Validate(d);devices=next;document.Devices=next;DeviceReferences.Assign(document);MarkDirty();UpdateGroups();Render();return true;}catch(Exception ex){MessageBox.Show(ex.Message,"Could not save");return false;}}
 void Edit(Device original){try{using(var dialog=new SharedDeviceEditor(original,devices.Select(d=>d.Group).Distinct().ToArray())){if(dialog.ShowDialog(this)!=DialogResult.OK)return;var next=new List<Device>(devices);if(original!=null)next.Remove(original);next.Add(dialog.Value);if(Commit(next)){statuses.Remove(dialog.Value.Id);statusDetails.Remove(dialog.Value.Id);Render();if(original==null)ViewDevice(dialog.Value);}}}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not open device editor");}}
 void Delete(Device d){if(MessageBox.Show("Delete '"+d.Name+"'?","Delete device",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;var next=new List<Device>(devices);next.Remove(d);Commit(next);}
 void Import(){using(var f=new OpenFileDialog{Filter="JSON configuration|*.json"}){if(f.ShowDialog()!=DialogResult.OK)return;try{var next=Config.Decode(File.ReadAllText(f.FileName));if(MessageBox.Show("Replace the current list with "+next.Count+" imported devices? Use Save first to keep the current network.","Import configuration",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;bool previous=loaded;loaded=true;if(!Commit(next))loaded=previous;else {statuses.Clear();statusDetails.Clear();connectionChecks.Clear();}Render();}catch(Exception ex){MessageBox.Show(ex.Message,"Import failed");}}}
 void Export(){using(var f=new SaveFileDialog{Filter="JSON configuration|*.json",FileName="homelab-devices-v5.json"}){if(f.ShowDialog()!=DialogResult.OK)return;try{File.WriteAllText(f.FileName,Config.Encode(devices));}catch(Exception ex){MessageBox.Show(ex.Message,"Export failed");}}}
 void CheckProgress(string message){if(IsDisposed||checkProgress==null)return;checkProgress.Text=message;help.SetToolTip(checkProgress,message);checkProgress.Refresh();}
 protected virtual async Task<ConnectionCheck> PingConnection(NetworkConnection c){var result=new ConnectionCheck{Address=c.Address,Time=DateTime.Now};if(c.Address.Length==0){result.Message="Address not recorded";return result;}try{using(var ping=new Ping()){var reply=await ping.SendPingAsync(c.Address,1000);result.Responding=reply.Status==IPStatus.Success;result.Message=result.Responding?"Responding · "+reply.RoundtripTime+" ms":"No ping reply";}}catch{result.Message="Check unavailable";}result.Time=DateTime.Now;return result;}
 protected virtual Task<ArpResult> ArpConnection(NetworkConnection c){return ArpDiscovery.ResolveAsync(c.Address);}
 protected virtual Task<List<PortResult>> CheckPorts(NetworkConnection c){return PortChecks.Check(c);}
 async Task Check(){if(checking)return;var snapshot=devices.ToArray();int total=snapshot.Sum(d=>d.Connections.Count);if(total==0){CheckProgress("Nothing to check — no network addresses are configured.");return;}checking=true;refresh.Enabled=false;refresh.Text="Checking…";checkMenu.Enabled=false;checkMenu.Text="Checking…";int generation=documentGeneration,done=0,replies=0,missing=0,unavailable=0,macs=0,mismatches=0,openPorts=0,portsTested=0;try{CheckProgress("Starting status check — "+total+" connections.");foreach(var d in snapshot){var results=new List<string>();int responding=0;foreach(var c in d.Connections){if(IsDisposed||generation!=documentGeneration)return;CheckProgress("Checking "+(done+1)+"/"+total+" — "+d.Name+" · "+c.Name+" · "+(c.Address.Length==0?"no address (skipping)":"pinging "+c.Address));var result=await PingConnection(c);if(IsDisposed||generation!=documentGeneration)return;CheckProgress("Checking "+(done+1)+"/"+total+" — "+d.Name+" · "+c.Name+" · ARP / MAC lookup "+c.Address);result.Arp=await ArpConnection(c);if(IsDisposed||generation!=documentGeneration)return;if(result.Arp.Mac.Length>0){macs++;if(ArpDiscovery.Compare(DeviceConnections.Get(c.Details,"MAC"),result.Arp.Mac)=="MAC MISMATCH")mismatches++;}CheckProgress("Checking "+(done+1)+"/"+total+" — "+d.Name+" · "+c.Name+" · TCP: "+String.Join(", ",PortChecks.Targets(c).Select(p=>p.Service+" "+p.Host+":"+p.Port)));result.Ports=await CheckPorts(c);if(IsDisposed||generation!=documentGeneration)return;openPorts+=result.Ports.Count(p=>p.Open);portsTested+=result.Ports.Count;result.Time=DateTime.Now;done++;if(result.Responding){responding++;replies++;}if(result.Message=="Address not recorded")missing++;if(result.Message=="Check unavailable")unavailable++;connectionChecks[c.Id]=result;results.Add(c.Name+": "+result.Message+"\r\n"+ArpDiscovery.Describe(c,result)+"\r\n"+PortChecks.Describe(result));CheckProgress("Checked "+done+"/"+total+" — "+d.Name+" · "+c.Name+": "+result.Message);}statuses[d.Id]=(responding>0?"● ":"○ ")+responding+"/"+d.Connections.Count+" responding · "+DateTime.Now.ToString("HH:mm");statusDetails[d.Id]=String.Join("\n",results);}Render();CheckProgress("Check complete at "+DateTime.Now.ToString("HH:mm:ss")+" — "+done+" connections: "+replies+" responding, "+(done-replies-missing-unavailable)+" no reply, "+missing+" without an address, "+unavailable+" unavailable; "+macs+" MACs resolved, "+mismatches+" mismatches; TCP "+openPorts+"/"+portsTested+" open.");}catch(Exception ex){CheckProgress("Check stopped after "+done+"/"+total+" connections: "+ex.Message);}finally{checking=false;if(!IsDisposed){refresh.Enabled=true;refresh.Text="Check status";checkMenu.Enabled=true;checkMenu.Text="Check status";}}}
 ConnectionCheck CheckFor(NetworkConnection c){ConnectionCheck value;return connectionChecks.TryGetValue(c.Id,out value)&&value.Address==c.Address?value:null;}
 NetworkConnection DisplayConnection(Device d){return d.Connections.FirstOrDefault(c=>CheckFor(c)!=null&&CheckFor(c).Responding)??d.Connections.FirstOrDefault(c=>c.Address.Length>0)??d.Connections.FirstOrDefault();}
 string ShortAddress(Device d){var c=DisplayConnection(d);return c==null?"No connections":c.Name+": "+(c.Address.Length>0?c.Address:"not recorded");}
 string AddressText(Device d){var c=DisplayConnection(d);var active=c!=null&&CheckFor(c)!=null&&CheckFor(c).Responding;return (active?"Last responding address":"Configured address")+"\r\n"+ShortAddress(d);}
 Color StatusColour(Device d){return d.Connections.Any(c=>CheckFor(c)!=null&&CheckFor(c).Responding)?Accent:Muted;}
 string StatusText(Device d){var checks=d.Connections.Select(CheckFor).Where(c=>c!=null).ToArray();if(checks.Length==0)return "Not checked";int replies=checks.Count(c=>c.Responding);return (replies>0?(replies>1?replies+" responding":"Responding"):checks.All(c=>c.Message=="Address not recorded")?"No address":checks.All(c=>c.Message=="Check unavailable")?"Check unavailable":"No ping reply")+" · "+checks.Max(c=>c.Time).ToString("dd MMM HH:mm");}
 void ApplyNetworkLists(HlbDocument edited){DeviceReferences.Assign(edited);document.Devices=devices=edited.Devices;document.Lookups=edited.Lookups;document.Mnemonics=edited.Mnemonics;document.ReferenceCounters=edited.ReferenceCounters;LookupStore.DocumentLists=document.Lookups;DeviceReferences.Current=document;MarkDirty();UpdateGroups();Render();}
 void Settings(){var current=CaptureDocument();string before=HlbFile.Encode(current);using(var dialog=new SettingsDialog(current,ApplyNetworkLists)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{if(testMode)UiPreferences.Current=dialog.Value;else UiPreferences.Save(dialog.Value);if(before!=HlbFile.Encode(dialog.NetworkValue))ApplyDocument(dialog.NetworkValue,networkFile,true);else{viewMode.SelectedItem=dialog.Value.View;SetZoom(dialog.Value.Zoom);}}catch(Exception ex){MessageBox.Show(ex.Message,"Could not apply settings");}}}
 bool SaveDevice(Device d){var next=new List<Device>(devices);int index=next.FindIndex(x=>x.Id==d.Id);if(index<0)return false;next[index]=d;return Commit(next);}
 void ViewDevice(Device d){try{using(var dialog=new DeviceDetails(d,devices.Select(x=>x.Group).Distinct().ToArray(),SaveDevice,CheckFor,StatusText,AddressText))dialog.ShowDialog(this);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not open device details");}}
 static void Launch(string target){try{Process.Start(new ProcessStartInfo(target){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message,"Could not open shortcut");}}
 static void Run(string app,string arguments){try{Process.Start(new ProcessStartInfo(app,arguments){UseShellExecute=true});}catch(Exception ex){MessageBox.Show("This shortcut requires the corresponding Windows client.\n\n"+ex.Message,"Could not launch");}}
}
public class LookupStore {
 public const int MaxEntries=1000;
 public static Dictionary<string,List<string>> DocumentLists;public static Action DocumentChanged;
 public static Dictionary<string,List<string>> Defaults(){using(var stream=typeof(LookupStore).Assembly.GetManifestResourceStream("lookups.json"))using(var reader=new StreamReader(stream))return Read(reader.ReadToEnd());}
 public Dictionary<string,List<string>> Lists {get;private set;}
 readonly string path;
 public LookupStore(string customPath=null){
  if(customPath==null&&DocumentLists!=null){Lists=DocumentLists;return;}path=customPath??Path.Combine(Config.Folder,"lookups.json");
  using(var stream=typeof(LookupStore).Assembly.GetManifestResourceStream("lookups.json"))using(var reader=new StreamReader(stream))Lists=Read(reader.ReadToEnd());
  if(File.Exists(path)){var saved=Read(File.ReadAllText(path));foreach(var pair in saved){if(!Lists.ContainsKey(pair.Key))Lists[pair.Key]=new List<string>();foreach(var item in pair.Value)if(!Lists[pair.Key].Contains(item,StringComparer.OrdinalIgnoreCase))Lists[pair.Key].Add(item);}}
 }
 static Dictionary<string,List<string>> Read(string json){var result=new JavaScriptSerializer().Deserialize<Dictionary<string,List<string>>>(json);if(result==null||result.Any(p=>p.Value==null||p.Value.Any(v=>String.IsNullOrWhiteSpace(v))))throw new Exception("Invalid lookup configuration. Restore lookups.json from its backup before editing devices.");return result;}
 public string Add(string field,string value){
  value=(value??"").Trim();if(value.Length==0)throw new Exception("Enter a value.");if(value.Length>(field=="Category"?60:100))throw new Exception("The value is too long.");
  if(!Lists.ContainsKey(field))throw new Exception("Unknown lookup list.");
  if(Lists[field].Count>=MaxEntries)throw new Exception("A list can contain up to "+MaxEntries+" entries.");
  if(Lists[field].Contains(value,StringComparer.OrdinalIgnoreCase))throw new Exception("This entry already exists. Select it from the list.");
  var next=Lists.ToDictionary(p=>p.Key,p=>new List<string>(p.Value));next[field].Add(value);
  if(path==null){Lists=next;DocumentLists=next;if(DocumentChanged!=null)DocumentChanged();return value;}Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";File.WriteAllText(temp,new JavaScriptSerializer().Serialize(next));if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);Lists=next;return value;
 }
}
