 sealed class AddChoice {public override string ToString(){return "Add new…";}}
 public static ComboBox Choice(Control parent,string field,int x,int y,int width,string current,LookupStore store,IEnumerable<string> extra=null){parent.Controls.Add(new Label{Text=field=="Category"?"Category / group":field,Location=new Point(x,y),AutoSize=true});var combo=new ComboBox{Location=new Point(x,y+23),Width=width,DropDownStyle=ComboBoxStyle.DropDownList,IntegralHeight=false,DropDownHeight=320,MaxDropDownItems=16,DropDownWidth=Math.Max(width,320)};var values=new List<string>(store.Lists[field]);if(extra!=null)values.AddRange(extra);values.Add(current??"");Action<string> fill=selected=>{combo.Items.Clear();combo.Items.Add("");foreach(var v in values.Where(v=>!String.IsNullOrWhiteSpace(v)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(v=>v))combo.Items.Add(v);combo.Items.Add(new AddChoice());combo.SelectedItem=combo.Items.OfType<string>().FirstOrDefault(v=>String.Equals(v,selected,StringComparison.OrdinalIgnoreCase))??"";};fill(current);string previous=combo.Text;
 combo.SelectionChangeCommitted+=(s,e)=>{if(combo.SelectedItem is AddChoice){using(var dialog=new AddLookupDialog(store,field,combo.Items.OfType<string>())){if(dialog.ShowDialog(parent.FindForm())==DialogResult.OK){values.Add(dialog.NewValue);fill(dialog.NewValue);previous=combo.Text;}else combo.SelectedItem=previous;}}else previous=combo.Text;};parent.Controls.Add(combo);return combo;}
 public static DataGridView Grid(Control parent,Dictionary<string,string> values,int y,int height){var grid=new DataGridView{Location=new Point(20,y),Size=new Size(690,height),BackgroundColor=Dashboard.PanelBg,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,RowHeadersVisible=false};grid.DefaultCellStyle.BackColor=Dashboard.PanelBg;grid.DefaultCellStyle.ForeColor=Dashboard.Ink;grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(45,90,100);grid.Columns.Add("Field","Field");grid.Columns.Add("Value","Value");foreach(var pair in values)grid.Rows.Add(pair.Key,pair.Value);parent.Controls.Add(grid);return grid;}
 public static Dictionary<string,string> Read(DataGridView grid){grid.EndEdit();var result=new Dictionary<string,string>();foreach(DataGridViewRow row in grid.Rows){if(row.IsNewRow)continue;var key=Convert.ToString(row.Cells[0].Value).Trim();if(key.Length==0)continue;if(result.ContainsKey(key))throw new Exception("Duplicate detail: "+key);result[key]=Convert.ToString(row.Cells[1].Value);}return result;}
 public static void Style(Form form,string title){form.Text=title;form.ClientSize=new Size(750,670);form.MinimumSize=new Size(766,709);form.StartPosition=FormStartPosition.CenterParent;form.BackColor=Dashboard.Bg;form.ForeColor=Dashboard.Ink;form.Font=new Font("Segoe UI",10);}
