 public static void Open(string value){try{Process.Start(new ProcessStartInfo(value){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message,"Could not open");}}
 public static void Run(string executable,string arguments){try{Process.Start(new ProcessStartInfo(executable,arguments){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message,"Could not launch client");}}
 public static string Quote(string value){return "\""+System.Text.RegularExpressions.Regex.Replace(value,@"(\\*)\""", "$1$1\\\"")+new string('\\',value.Reverse().TakeWhile(c=>c=='\\').Count())+"\"";}
 public static string Host(NetworkConnection c,string kind){var a=c.Access??AccessOptions.Defaults();string h=kind=="SSH"?a.SshHost:kind=="RDP"?a.RdpHost:a.ShareHost;return String.IsNullOrWhiteSpace(h)?c.Address:h;}
 public static bool Available(NetworkConnection c,string kind){return kind=="Dashboard"?!String.IsNullOrWhiteSpace(c.Url):!String.IsNullOrWhiteSpace(Host(c,kind));}
 public static string SshArguments(NetworkConnection c){var a=c.Access??AccessOptions.Defaults();a.Validate();Config.ValidateEndpoint(Host(c,"SSH"),"");return "-p "+a.SshPort+(a.SshUser.Length>0?" -l "+Quote(a.SshUser):"")+(a.SshKey.Length>0?" -i "+Quote(a.SshKey):"")+" "+Quote(Host(c,"SSH"));}
 public static string RdpDefinition(NetworkConnection c){var a=c.Access??AccessOptions.Defaults();a.Validate();string h=Host(c,"RDP");Config.ValidateEndpoint(h,"");if(h.Contains(":"))h="["+h+"]";return "full address:s:"+h+":"+a.RdpPort+"\r\nusername:s:"+a.RdpUser+"\r\nscreen mode id:i:"+(a.FullScreen?2:1)+"\r\ndesktopwidth:i:"+a.Width+"\r\ndesktopheight:i:"+a.Height+"\r\nprompt for credentials:i:1\r\n";}
 public static string ShareTarget(NetworkConnection c){var a=c.Access??AccessOptions.Defaults();a.Validate();string h=Host(c,"Shared");Config.ValidateEndpoint(h,"");if(h.Contains(":"))h=h.Replace(":","-")+".ipv6-literal.net";return "\\\\"+h+(a.SharePath.Length==0?"":"\\"+a.SharePath.Replace('/','\\'));}
 public static void Ssh(NetworkConnection c){try{Run(UiPreferences.Current.SshClient,SshArguments(c));}catch(Exception ex){MessageBox.Show(ex.Message,"Could not open SSH");}}
 public static void Rdp(NetworkConnection c){try{var folder=Path.Combine(Config.Folder,"rdp");Directory.CreateDirectory(folder);string name;using(var hash=System.Security.Cryptography.SHA256.Create())name=BitConverter.ToString(hash.ComputeHash(System.Text.Encoding.UTF8.GetBytes(c.Id))).Replace("-","");var path=Path.Combine(folder,name+".rdp");File.WriteAllText(path,RdpDefinition(c),System.Text.Encoding.Unicode);Run(UiPreferences.Current.RdpClient,Quote(path));}catch(Exception ex){MessageBox.Show(ex.Message,"Could not open RDP");}}
 public static void Files(NetworkConnection c){try{Open(ShareTarget(c));}catch(Exception ex){MessageBox.Show(ex.Message,"Could not open shared folder");}}
}
