public static class Program {
 [STAThread] public static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Contains("--self-test")){try{var d=new Device{Name="Router",Address="192.168.1.1",Url="http://192.168.1.1",Group="Network"};Config.Validate(d);var round=Config.Decode(Config.Encode(new List<Device>{d}));if(round.Count!=1||round[0].Name!="Router")throw new Exception("Round trip failed");foreach(var bad in new[]{"file:///C:/Windows","javascript:alert(1)","https://user:password@example.com"}){bool rejected=false;try{Config.Validate(new Device{Name="Bad",Address="localhost",Url=bad});}catch{rejected=true;}if(!rejected)throw new Exception("Unsafe URL accepted");}using(var form=new Dashboard(true)){form.Show();Application.DoEvents();if(args.Length>1){using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(args[1]);}}form.Close();}File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"self-test.txt"),"PASS: configuration round trip, URL validation, form construction and render.");return 0;}catch(Exception ex){File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"self-test.txt"),ex.ToString());return 1;}}Application.Run(new Dashboard());return 0;}
}








