public class AccessOptions {
 public string SshHost {get;set;} public int SshPort {get;set;} public string SshUser {get;set;} public string SshKey {get;set;}
 public string RdpHost {get;set;} public int RdpPort {get;set;} public string RdpUser {get;set;} public bool FullScreen {get;set;} public int Width {get;set;} public int Height {get;set;}
 public string ShareHost {get;set;} public string SharePath {get;set;}
 public AccessOptions(){SshHost=SshUser=SshKey=RdpHost=RdpUser=ShareHost=SharePath="";SshPort=22;RdpPort=3389;Width=1280;Height=800;}
 public static AccessOptions Defaults(){return new AccessOptions{SshPort=UiPreferences.Current.SshPort,SharePath=UiPreferences.Current.Share??""};}
 public void Validate(){SshHost=(SshHost??"").Trim();RdpHost=(RdpHost??"").Trim();ShareHost=(ShareHost??"").Trim();SshUser=(SshUser??"").Trim();RdpUser=(RdpUser??"").Trim();SshKey=(SshKey??"").Trim();SharePath=(SharePath??"").Trim().Trim('\\','/');Config.ValidateEndpoint(SshHost,"");Config.ValidateEndpoint(RdpHost,"");Config.ValidateEndpoint(ShareHost,"");
  if(SshPort<1||SshPort>65535||RdpPort<1||RdpPort>65535)throw new Exception("Ports must be between 1 and 65535.");
  if(Width<320||Width>7680||Height<200||Height>4320)throw new Exception("RDP size must be 320–7680 wide and 200–4320 high.");
  if(new[]{SshUser,RdpUser,SshKey,SharePath}.Any(x=>x.Any(Char.IsControl)))throw new Exception("Connection fields must be single-line values.");
  if(SshKey.Contains("\"")||SshUser.Contains("\""))throw new Exception("SSH fields cannot contain quotation marks.");
  if(SharePath.IndexOfAny(new[]{'\"','<','>','|','?', '*',':'})>=0||SharePath.Split('\\','/').Contains(".."))throw new Exception("Enter a share name or a relative folder path.");
 }
}
public class AccessEditor:Form {
