   }
  }
  var save=Dashboard.Btn("Save",()=>{try{if(kind=="Dashboard")draft.Url=url.Text.Trim();else if(kind=="SSH"){a.SshHost=host.Text;a.SshPort=(int)port.Value;a.SshUser=user.Text;a.SshKey=key.Text;}else if(kind=="RDP"){a.RdpHost=host.Text;a.RdpPort=(int)port.Value;a.RdpUser=user.Text;a.FullScreen=full.Checked;a.Width=(int)width.Value;a.Height=(int)height.Value;}else{a.ShareHost=host.Text;a.SharePath=share.Text;}a.Validate();Config.ValidateEndpoint(draft.Address,draft.Url);Value=draft;saving=true;DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Check connection settings");}});save.Location=new Point(370,440);Controls.Add(save);var cancel=Dashboard.Btn("Cancel",()=>Close());cancel.Location=new Point(470,440);Controls.Add(cancel);CancelButton=cancel;initial=State();FormClosing+=(s,e)=>{if(!saving&&initial!=State()&&MessageBox.Show(this,"Discard unsaved connection settings?","Unsaved changes",MessageBoxButtons.YesNo)!=DialogResult.Yes)e.Cancel=true;};
 }
